function freezeDefinition(value) {
  if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) freezeDefinition(child);
  return Object.freeze(value);
}
freezeDefinition(ATTRIBUTES);
freezeDefinition(NEUTRAL_ATTRIBUTE);
freezeDefinition(ROLE_SPECIALIZATION);
for (const definition of [...UNITS, ...ENEMIES]) definition.effects ??= {};
freezeDefinition(UNITS);
freezeDefinition(ENEMIES);
freezeDefinition(SIGNATURE_ABILITIES);
freezeDefinition(EXTRA_ATTRIBUTES);
freezeDefinition(COMMON_ABILITIES);
freezeDefinition(OPTIONAL_ABILITIES);
freezeDefinition(MOVEMENT_ROLES);
freezeDefinition(RANGE_UNIT_IDS);
const unitById = new Map(UNITS.map(unit => [unit.id, unit]));
const enemyById = new Map(ENEMIES.map(enemy => [enemy.id, enemy]));
export const getUnit = id => unitById.get(id) ?? null;
export const getEnemy = id => enemyById.get(id) ?? null;
export const getCharacter = (id, team) => team === "enemy" ? getEnemy(id) : team === "player" ? getUnit(id) : getUnit(id) ?? getEnemy(id);
